154	// whole-tensor TMA load path with a cp.async GATHER that swizzle-stores packed-Q and paged/contig
155	// K/V into the SAME 128B-swizzle smem layout the descriptors expect (tma_swz_test{,_v}.cu proved
156	// this layout reproduces TMA byte-for-byte). Epilogue scatters O/LSE via the pack-GQA divmod.
157	// ======================================================================================
158	namespace pf {
159	// PF_CPASYNC=1: pipelined cp.async gather loaders (fast path). =0: synchronous uint4 stores (debug).
