163	constexpr int CTA_M = 128, CTA_N = 128, HD = 128, WG = 128;
164	constexpr int NThreads = 3 * WG, NumCons = 2 * WG, NumProd = WG, WS_STAGES = 3;
165	constexpr int KVSTRIDE = CTA_N * HD;            // one swizzled K/V tile (elems)
