199	__device__ __forceinline__ float quad_max(float v) {
200	    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, 1));
201	    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, 2));
202	    return v;
