209	__device__ __forceinline__ uint32_t pack_bf16(float lo, float hi) {
210	    __nv_bfloat16 a = __float2bfloat16_rn(lo), b = __float2bfloat16_rn(hi);
211	    uint16_t ua, ub; memcpy(&ua, &a, 2); memcpy(&ub, &b, 2);
212	    return uint32_t(ua) | (uint32_t(ub) << 16);
213	}
214	// Pack two fp32 into the wgmma A/B register pair for the QKV element type T (bf16 or fp16). Both
215	// are 16-bit so the smem/swizzle layout is byte-identical; only the wgmma type token and pack differ.
216	template <typename T> __device__ __forceinline__ uint32_t pack_2x(float lo, float hi);
217	template <> __device__ __forceinline__ uint32_t pack_2x<__nv_bfloat16>(float lo, float hi) { return pack_bf16(lo, hi); }
218	template <> __device__ __forceinline__ uint32_t pack_2x<__half>(float lo, float hi) {
219	    __half a = __float2half_rn(lo), b = __float2half_rn(hi);
220	    uint16_t ua, ub; memcpy(&ua, &a, 2); memcpy(&ub, &b, 2);
221	    return uint32_t(ua) | (uint32_t(ub) << 16);
222	}
