1197	        }
1198	        bool bad = (l_r[r] == 0.f || l_r[r] != l_r[r]);
1199	        float inv = bad ? 0.f : 1.f / l_r[r];
1200	        const float invvd = inv * vd;                  // v_descale folds into the normalized output (fp8)
1201	        float lse_v = bad ? -INFINITY : mr * sc_eff + __logf(l_r[r]);
1202	        if (num_splits > 1) {
1203	            // write the NORMALIZED split partial (O_s, lse_s); combine_kernel does the cross-split reduce.
1204	            const int hq = hkv * rep;
1205	            float* op = Opart + (((long)split * total_q + qidx) * hq + qhead) * HDV;
1206	#pragma unroll
1207	            for (int c = 0; c < HDV / 8; ++c) {
1208	                int dv0 = 8 * c + 2 * tg;
1209	                if (val) { op[dv0] = acc_o[c*4+r*2+0] * invvd; op[dv0+1] = acc_o[c*4+r*2+1] * invvd; }
1210	            }
1211	            if (tg == 0 && val) LSEpart[((long)split * hq + qhead) * total_q + qidx] = lse_v;
1212	        } else {
1213	            long obase = (long)qidx * o_row + (long)qhead * o_head;
1214	#pragma unroll
1215	            for (int c = 0; c < HDV / 8; ++c) {
1216	                int dv0 = 8 * c + 2 * tg;
1217	                uint32_t o = pack_2x<TC>(acc_o[c*4+r*2+0] * invvd, acc_o[c*4+r*2+1] * invvd);
1218	                if (val) *reinterpret_cast<uint32_t*>(&O[obase + dv0]) = o;
1219	            }
1220	            if (tg == 0 && val) LSE[(long)qhead * total_q + qidx] = lse_v;
1221	        }
1222	    }
1223	}
1224	
1225	// ===================== persistent continuous-ring prefill (hd128 bf16 TMA) =====================
1226	// FA3-style persistent kernel: each CTA grabs work-items off a static stride (work = blockIdx.x +
1227	// k*gridDim.x) and processes them in a loop. The win vs the per-tile prefill_kernel is that the K/V
1228	// ring is ONE CONTINUOUS stream across work-items -- PipelineState (the ring index g + its phase) is
1229	// declared once and NEVER reset per item, so the producer prefetches the next item's K/V into slots
1230	// the consumer just freed, with no per-item pipeline-fill bubble. (The earlier naive per-item-reinit
1231	// persistent attempt regressed precisely because it paid that fill + barrier-reinit cost every item.)
1232	//
1233	// Q is single-buffered with a barQf/barQe ping-pong (phase = witer&1): the producer waits barQe (the
1234	// consumer freed the prior Q), reloads Q -- via ONE async TMA box-set (rep==1, mapQ) so the reload is
1235	// cheap enough to hide behind the continuous ring; GQA/paged would fall back to the cp.async gather --
1236	// then signals barQf. To keep the ring primed across the boundary the producer issues the item's FIRST
1237	// K/V tile (empty-gated on the global g, NOT Q-gated) BEFORE the barQe wait, then floods the rest after
1238	// Q. Stage index / phase everywhere use the GLOBAL counter g so
1239	// producer and consumer stay in lock-step (both advance g by n_cnt per non-empty item, skip empties
1240	// identically). num_splits is implicitly 1 (prefill); no split-KV epilogue. TMA-only (routed so).
1241	template <typename TIn, typename TC, int HD, int HDV, bool USE_TMA, bool EXTRA, int STAGES, int CN = CTA_N,
1242	          int CM = CTA_M, int MINB = 1>
1243	__global__ __launch_bounds__(WG * (1 + CM / 64), MINB) void prefill_persist_kernel(

