2420	// One warp = one (b, hk, split). MAXM bounds the packed-GQA rows; per/perv = HD/32, HDV/32 dims/lane.
2421	template <typename TIn, typename TOut, int HD, int HDV, int MAXM>
2422	__global__ void decode_kernel(
2423	        const TIn* __restrict__ Q, const TIn* __restrict__ K, const TIn* __restrict__ V,
2424	        float* __restrict__ Opart, float* __restrict__ LSEpart,
2425	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
2426	        const int* __restrict__ page_table,
2427	        const float* __restrict__ q_descale, const float* __restrict__ k_descale, const float* __restrict__ v_descale,
2428	        int ds_b, int ds_h,
2429	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2430	        int batch, int hq, int hkv, int rep, int total_q, int block_size, int page_stride,
2431	        int num_splits, float scale, float softcap, int win_l, int win_r, int causal) {
2432	    constexpr int per = HD / 32, perv = HDV / 32;
2433	    const int witem = blockIdx.x * WARPS_PER_BLOCK + (threadIdx.x >> 5);
2434	    const int lane = threadIdx.x & 31;
2435	    if (witem >= num_splits * hkv * batch) return;
2436	    // work-item -> (b, hk, split)
2437	    const int split = witem % num_splits;
2438	    int tmp = witem / num_splits;
2439	    const int hk = tmp % hkv;
2440	    const int b = tmp / hkv;
2441	    // b is bounded by the launch (grid sized to batch); guard:
2442	    const int q0 = cu_q[b];
2443	    const int sq = cu_q[b + 1] - q0;
2444	    if (sq <= 0) return;
2445	    const int klen = seqused_k ? seqused_k[b] : (cu_k[b + 1] - cu_k[b]);
2446	    const int M = sq * rep;
2447	
2448	    const long ds_idx = (long)b * ds_b + (long)hk * ds_h;
2449	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
2450	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
2451	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
2452	    const float qk_scale = scale * qd * kd;
2453	
2454	    // split's key range
2455	    const int span = (klen + num_splits - 1) / num_splits;
2456	    const int jlo = split * span;
2457	    const int jhi = min(jlo + span, klen);
