2459	    float qreg[MAXM][per];
2460	    float acc[MAXM][perv];
2461	    float mrow[MAXM], lrow[MAXM];
2462	    int qabs[MAXM];
2463	#pragma unroll
2464	    for (int mi = 0; mi < MAXM; ++mi) {
2465	        if (mi >= M) break;
2466	        const int qpos = mi / rep, r = mi % rep;
2467	        const int head = hk * rep + r;
2468	        const TIn* qp = Q + (long)(q0 + qpos) * q_row + (long)head * q_head;
2469	#pragma unroll
2470	        for (int e = 0; e < per; ++e) qreg[mi][e] = to_float<TIn>(qp[lane * per + e]);
2471	#pragma unroll
2472	        for (int e = 0; e < perv; ++e) acc[mi][e] = 0.f;
2473	        mrow[mi] = -INFINITY; lrow[mi] = 0.f;
2474	        qabs[mi] = klen - sq + qpos;
2475	    }
