2477	    // Software-pipelined K/V load: issue key (j+1)'s gmem loads (including the dependent page_table
2478	    // lookup) while computing on key j, so the load latency overlaps the (short) softmax compute.
2479	    auto load_key = [&](int j, float* kx, float* vx) {
2480	        long krow;
2481	        if (page_table) { int blk = page_table[(long)b * page_stride + j / block_size]; krow = (long)blk * block_size + (j % block_size); }
2482	        else            { krow = (long)cu_k[b] + j; }
2483	        const TIn* kp = K + krow * k_row + (long)hk * k_head;
2484	        const TIn* vp = V + krow * v_row + (long)hk * v_head;
2485	#pragma unroll
2486	        for (int e = 0; e < per; ++e)  kx[e] = to_float<TIn>(kp[lane * per + e]);
2487	#pragma unroll
2488	        for (int e = 0; e < perv; ++e) vx[e] = to_float<TIn>(vp[lane * perv + e]);
2489	    };
2490	    float kxA[per], vxA[perv], kxB[per], vxB[perv];
2491	    if (jlo < jhi) load_key(jlo, kxA, vxA);
2492	    for (int j = jlo; j < jhi; ++j) {
2493	        const bool A = ((j - jlo) & 1) == 0;
2494	        float* kx = A ? kxA : kxB; float* vx = A ? vxA : vxB;
2495	        if (j + 1 < jhi) load_key(j + 1, A ? kxB : kxA, A ? vxB : vxA);   // prefetch next
2496	#pragma unroll
